-- Riparazione incidente 2026-08-27: uno statement della migration
-- 20260827030000_rhs_varieta_arbusti_batch01 e' stato applicato senza
-- clausola WHERE (errore di trascrizione manuale della query, non dello
-- script generatore) e ha toccato tutte le 9042 righe di specie invece
-- della sola riga amelanchier-lamarckii. Rimuove il testo/alert/fonte
-- iniettati ovunque (idempotente: no-op dove il testo non e' presente) e
-- ricostruisce stato_verifica dalla cronologia esatta delle migration gia'
-- committate in git (227 verificato prima della Fase 5 RHS, 387 alla fine
-- della Fase 5, + le 6 specie del batch arbusti di oggi effettivamente
-- applicate con la propria WHERE corretta prima che la query si
-- interrompesse = 393 totali; le altre 20 specie del batch odierno restano
-- 'bozza', da rifare in un batch successivo). Vedi scripts/rhs-import/ e
-- fonti/criterio-importazione.md.

update specie set descrizione = replace(descrizione, $t$ Da RHS (testo originale in inglese): "A medium-sized, deciduous, spreading shrub or small tree with narrowly obovate leaves and racemes of star-shaped white flowers in spring, followed by round, purple-black fruit. Good autumn colour". RHS elenca 5 cultivar coltivate con altezze da 1-8m e diffusione da 1-8m (tra cui 'Prince Charles', 'R.J. Hilton', 'Snow Cloud', 'Snowflakes').$t$, '');

update specie set fonti = array_remove(fonti, $t$RHS (rhs.org.uk) — Amelanchier lamarckii$t$);

update specie
set alert = (
  select coalesce(array_agg(x), '{}'::text[]) from unnest(alert) x
  where x not in (
    $t$Da RHS (testo originale in inglese) — Parassiti: "Generally pest-free"; Malattie: "Generally disease-free"$t$,
    $t$Rusticità RHS: H6 (scala UK, vedi H1-H7 nella documentazione RHS)$t$,
    $t$Dimensioni RHS a maturità: altezza 1-8m, diffusione 1-8m$t$,
    $t$Potatura (RHS, testo originale in inglese): "pruning group 1"$t$,
    $t$Propagazione (RHS, testo originale in inglese): "Propagate by soil originale in inglese): "Propagate by soil layering, or take root cuttings when dormant"$t$
  )
)
where alert is not null and alert && ARRAY[
  $t$Da RHS (testo originale in inglese) — Parassiti: "Generally pest-free"; Malattie: "Generally disease-free"$t$,
    $t$Rusticità RHS: H6 (scala UK, vedi H1-H7 nella documentazione RHS)$t$,
    $t$Dimensioni RHS a maturità: altezza 1-8m, diffusione 1-8m$t$,
    $t$Potatura (RHS, testo originale in inglese): "pruning group 1"$t$,
    $t$Propagazione (RHS, testo originale in inglese): "Propagate by soil originale in inglese): "Propagate by soil layering, or take root cuttings when dormant"$t$
];

update specie set esigenze = esigenze - 'luce' - 'acqua' - 'terreno'
where esigenze->>'luce' = $t$Pieno sole$t$
  and esigenze->>'acqua' = $t$Umido ma ben drenato, ben drenato$t$
  and esigenze->>'terreno' = $t$Argilloso, franco, sabbioso; pH acido, neutro$t$;

